class Solution:
    def subarrayGCD(self, nums, k):
        from math import gcd
        n=len(nums); ans=0
        for i in range(n):
            g=0
            for j in range(i,n):
                g=gcd(g,nums[j])
                if g==k: ans+=1
                elif g<k: break
        return ans

