class Solution {
    public int subarrayGCD(int[] nums, int k){
        int n=nums.length,ans=0;
        for(int i=0;i<n;i++){
            int g=0;
            for(int j=i;j<n;j++){
                g=gcd(g,nums[j]);
                if(g==k) ans++;
                else if(g<k) break;
            }
        }
        return ans;
    }
    int gcd(int a,int b){return b==0?a:gcd(b,a%b);}
}

