var subarrayGCD = function(nums, k) {
    const gcd=(a,b)=>b?gcd(b,a%b):a;
    let ans=0;
    for(let i=0;i<nums.length;i++){
        let g=0;
        for(let j=i;j<nums.length;j++){
            g=gcd(g,nums[j]);
            if(g===k) ans++; else if(g<k) break;
        }
    }
    return ans;
};
